class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        items = list(tokens)
        while len(items) > 1:
            i = next(k for k, t in enumerate(items) if t in ("+", "-", "*", "/"))
            a, b, op = int(items[i - 2]), int(items[i - 1]), items[i]
            if op == "+":
                v = a + b
            elif op == "-":
                v = a - b
            elif op == "*":
                v = a * b
            else:
                v = abs(a) // abs(b) * (1 if (a < 0) == (b < 0) else -1)  # truncate toward zero
