public:
    int calculate(string s) {
        long long total = 0, last = 0, num = 0;
        char op = '+';
        for (size_t i = 0; i < s.size(); i++) {
            char c = s[i];
            if (isdigit(c)) num = num * 10 + (c - '0');
            if ((!isdigit(c) && c != ' ') || i == s.size() - 1) {
                if (op == '+' || op == '-') {
                    total += last;
                    last = op == '+' ? num : -num;
                } else if (op == '*') last *= num;
                else last /= num;
                op = c;
                num = 0;
            }
        }
        return (int) (total + last);
    }
};

